// Process event creation request
const data = $input.item.json;

// Create a structured event object
const eventData = {
  id: `EVENT-${Date.now()}`,
  createdAt: new Date().toISOString(),
  name: data.name || 'Untitled Event',
  type: data.type || 'Networking',
  description: data.description || '',
  startDate: data.startDate || '',
  endDate: data.endDate || '',
  location: data.location || '',
  virtualLink: data.virtualLink || '',
  isVirtual: !!data.virtualLink,
  capacity: data.capacity || 0,
  registrationLink: data.registrationLink || '',
  organizer: data.organizer || 'VC Firm',
  targetAudience: data.targetAudience || '',
  speakers: data.speakers || '',
  partners: data.partners || '',
  status: 'Planning',
  registrationCount: 0,
  tags: data.tags || '',
  notes: data.notes || ''
};

// Calculate event duration
if (eventData.startDate && eventData.endDate) {
  const start = new Date(eventData.startDate);
  const end = new Date(eventData.endDate);
  const durationMs = end - start;
  const durationHours = Math.round(durationMs / (1000 * 60 * 60) * 10) / 10;
  eventData.duration = durationHours;
}

return { json: eventData };

// Update event with calendar information
const eventData = $input.first().json;
const calendarData = $input.last().json;

// Combine data
const updatedEventData = {
  ...eventData,
  calendarEventId: calendarData.id,
  calendarEventLink: calendarData.htmlLink,
  calendarCreated: true,
  status: 'Scheduled',
  lastUpdated: new Date().toISOString()
};

// If virtual, extract conference details
if (calendarData.conferenceData && calendarData.conferenceData.entryPoints) {
  const conferenceLinks = calendarData.conferenceData.entryPoints
    .filter(entry => entry.uri)
    .map(entry => entry.uri);

  if (conferenceLinks.length > 0) {
    updatedEventData.virtualLink = conferenceLinks[0];
    updatedEventData.allConferenceLinks = conferenceLinks.join(', ');
  }
}

return { json: updatedEventData };

