};

return { json: registration };

// Update event with registration count
const registrationData = $input.first().json;
const eventData = $input.last().json;

// Combine data
const updatedEventData = {
  ...eventData,
  registrationCount: (parseInt(eventData.registrationCount) || 0) + 1,
  lastUpdated: new Date().toISOString()
};

// Check if event is at capacity
if (updatedEventData.capacity > 0 && updatedEventData.registrationCount >= updatedEventData.capacity) {
  updatedEventData.status = 'At Capacity';
}

// Combine with registration data for email
const combinedData = {
  ...updatedEventData,
  registration: registrationData
};

return { json: combinedData };

