// Check for events that need reminders
const upcomingEvents = $input.item.json;

// If no upcoming events, return empty
if (!upcomingEvents || !Array.isArray(upcomingEvents)) {
  return { json: { hasEvents: false } };
}

// Get current date
const now = new Date();

// Find events happening in the next 48 hours
const soonEvents = upcomingEvents.filter(event => {
  const eventDate = new Date(event.startDate);
  const timeDiff = eventDate.getTime() - now.getTime();
  const hoursDiff = timeDiff / (1000 * 60 * 60);
  return hoursDiff > 0 && hoursDiff <= 48;
});

// Find events happening in 7 days (for weekly reminder)
const weekEvents = upcomingEvents.filter(event => {
  const eventDate = new Date(event.startDate);
  const timeDiff = eventDate.getTime() - now.getTime();
  const daysDiff = timeDiff / (1000 * 60 * 60 * 24);
  return daysDiff > 6.5 && daysDiff <= 7.5;
});

// Combine events that need reminders
const reminderEvents = {
  hasEvents: soonEvents.length > 0 || weekEvents.length > 0,
  soonEvents,
  weekEvents
};

return { json: reminderEvents };

// Process soon events for reminders
const data = $input.item.json;
const soonEvents = data.soonEvents || [];

// Return array of events to process individually
return soonEvents.map(event => ({
  json: {
    ...event,
    reminderType: 'soon'
  }
}));

// Process week events for reminders
const data = $input.item.json;
const weekEvents = data.weekEvents || [];

// Return array of events to process individually
return weekEvents.map(event => ({
  json: {
    ...event,
    reminderType: 'week'
  }
}));

// Prepare event reminder data
const eventData = $input.first().json;
const registrations = $input.last().json || [];

// Format event date and time
const eventDate = new Date(eventData.startDate);
const formattedDate = eventDate.toLocaleDateString();
const formattedTime = eventDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

// Calculate hours until event
const now = new Date();
const hoursUntil = Math.round((eventDate - now) / (1000 * 60 * 60));

// Create reminder data
const reminderData = {
  ...eventData,
  registrations,
  registrationCount: registrations.length,
  formattedDate,
  formattedTime,
  hoursUntil,
  reminderSent: new Date().toISOString(),
  emailSubject: hoursUntil <= 24 
    ? `TOMORROW: ${eventData.name}` 
    : `Event Reminder: ${eventData.name} (${formattedDate})`,
  emailIntro: hoursUntil <= 24
    ? `This is a reminder that you are registered for our event tomorrow (${formattedDate}).`
    : `This is a reminder that you are registered for our upcoming event in ${hoursUntil} hours.`
};

return { json: reminderData };

// Prepare week event reminder data
const eventData = $input.first().json;
const registrations = $input.last().json || [];

// Format event date and time
const eventDate = new Date(eventData.startDate);
const formattedDate = eventDate.toLocaleDateString();
const formattedTime = eventDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

// Create reminder data
const reminderData = {
  ...eventData,
  registrations,
  registrationCount: registrations.length,
  formattedDate,
  formattedTime,
  reminderSent: new Date().toISOString(),
  emailSubject: `One Week Until: ${eventData.name}`,
  emailIntro: `This is a reminder that you are registered for our event next week on ${formattedDate}.`
};

return { json: reminderData };

