// Process check-in request
const data = $input.item.json;

// Create a structured check-in object
const checkin = {
  id: `CHECKIN-${Date.now()}`,
  checkinTime: new Date().toISOString(),
  eventId: data.eventId || '',
  registrationId: data.registrationId || '',
  attendeeEmail: data.email || '',
  checkinMethod: data.method || 'Manual',
  checkinNotes: data.notes || '',
  checkinBy: data.checkinBy || 'Staff'
};

return { json: checkin };

// Combine check-in, registration, and event data
const checkinData = $input.all()[0].json;
const registrationData = $input.all()[1].json;
const eventData = $input.all()[2].json;

// Create combined data object
const combinedData = {
  ...checkinData,
  registration: registrationData,
  event: eventData,
  attendeeName: registrationData.attendeeName,
  attendeeCompany: registrationData.attendeeCompany,
  eventName: eventData.name,
  formattedCheckinTime: new Date(checkinData.checkinTime).toLocaleTimeString()
};

return { json: combinedData };

// Check for completed events
const scheduledEvents = $input.item.json;

// If no scheduled events, return empty
if (!scheduledEvents || !Array.isArray(scheduledEvents)) {
  return { json: { hasCompletedEvents: false } };
}

// Get current date
const now = new Date();

// Find events that have ended
const completedEvents = scheduledEvents.filter(event => {
  const endDate = new Date(event.endDate);
  return endDate < now;
});

// Find events that ended in the last 24 hours (for feedback)
const recentlyCompletedEvents = scheduledEvents.filter(event => {
  const endDate = new Date(event.endDate);
  const timeDiff = now.getTime() - endDate.getTime();
  const hoursDiff = timeDiff / (1000 * 60 * 60);
  return hoursDiff > 0 && hoursDiff <= 24;
});

return {
  json: {
    hasCompletedEvents: completedEvents.length > 0,
    completedEvents,
    hasRecentlyCompletedEvents: recentlyCompletedEvents.length > 0,
    recentlyCompletedEvents
  }
};

// Process completed events
const data = $input.item.json;
const completedEvents = data.completedEvents || [];

// Return array of events to process individually
return completedEvents.map(event => ({ json: event }));

// Process recently completed events for feedback
const data = $input.item.json;
const recentEvents = data.recentlyCompletedEvents || [];

// Return array of events to process individually
return recentEvents.map(event => ({ json: event }));

// Prepare feedback request data
const eventData = $input.first().json;
const attendees = $input.last().json || [];

// Create feedback data
const feedbackData = {
  ...eventData,
  attendees,
  attendeeCount: attendees.length,
  feedbackUrl: `https://vcfirm.com/feedback?eventId=${eventData.id}`,
  formattedDate: new Date(eventData.startDate).toLocaleDateString()
};

return { json: feedbackData };

