// Generate event analytics report
const events = $input.all()[0].json || [];
const registrations = $input.all()[1].json || [];

// Get date range for the report
const now = new Date();
const lastMonth = new Date(now);
lastMonth.setMonth(now.getMonth() - 1);

// Format date range for display
const dateRangeString = `${lastMonth.toLocaleDateString()} - ${now.toLocaleDateString()}`;

// Filter events from the last month
const recentEvents = events.filter(event => {
  const eventDate = new Date(event.startDate);
  return eventDate >= lastMonth && eventDate <= now;
});

// Count events by status
const statusCount = {};
for (const event of events) {
  statusCount[event.status] = (statusCount[event.status] || 0) + 1;
}

// Count events by type
const typeCount = {};
for (const event of events) {
  typeCount[event.type] = (typeCount[event.type] || 0) + 1;
}

// Calculate registration metrics
const registrationsByEvent = {};
for (const reg of registrations) {
  registrationsByEvent[reg.eventId] = (registrationsByEvent[reg.eventId] || 0) + 1;
}

// Calculate check-in rates
const checkinsByEvent = {};
let totalCheckins = 0;
for (const reg of registrations) {
  if (reg.checkedIn === 'true') {
    checkinsByEvent[reg.eventId] = (checkinsByEvent[reg.eventId] || 0) + 1;
    totalCheckins++;
  }
}

// Find upcoming events
const upcomingEvents = events.filter(event => {
  const eventDate = new Date(event.startDate);
  return eventDate > now && event.status === 'Scheduled';
});

// Sort upcoming events by date
upcomingEvents.sort((a, b) => new Date(a.startDate) - new Date(b.startDate));

// Create analytics report
const analyticsReport = {
  reportDate: now.toISOString(),
  dateRange: dateRangeString,
  totalEvents: events.length,
  recentEvents: recentEvents.length,
  upcomingEvents: upcomingEvents.length,
  completedEvents: statusCount['Completed'] || 0,
  totalRegistrations: registrations.length,
  totalCheckins,
  checkinRate: registrations.length > 0 ? Math.round((totalCheckins / registrations.length) * 100) : 0,
  statusDistribution: JSON.stringify(statusCount),
  typeDistribution: JSON.stringify(typeCount),
  upcomingEventsList: upcomingEvents.slice(0, 5).map(e => `${e.name} (${new Date(e.startDate).toLocaleDateString()})`).join(', ')
};

return { json: analyticsReport };

